class Encrypter {
    unordered_map<char, string> enc;
    unordered_map<string, int> counts;

public:
    Encrypter(vector<char>& keys, vector<string>& values, vector<string>& dictionary) {
        for (int i = 0; i < (int)keys.size(); i++) {
            enc[keys[i]] = values[i];
        }
        for (const string& w : dictionary) {
            string e = encrypt(w);
            if (!e.empty()) {
                counts[e]++;
            }
        }
    }

    string encrypt(string word1) {
        string res = "";
        for (char c : word1) {
            if (!enc.count(c)) return "";
            res += enc[c];
        }
        return res;
    }

    int decrypt(string word2) {
        auto it = counts.find(word2);
        return it != counts.end() ? it->second : 0;
    }
};

class Encrypter {
    private Map<Character, String> enc = new HashMap<>();
    private Map<String, Integer> counts = new HashMap<>();

    public Encrypter(char[] keys, String[] values, String[] dictionary) {
        for (int i = 0; i < keys.length; i++) {
            enc.put(keys[i], values[i]);
        }
        for (String w : dictionary) {
            String e = encrypt(w);
            if (!e.isEmpty()) {
                counts.put(e, counts.getOrDefault(e, 0) + 1);
            }
        }
    }

    public String encrypt(String word1) {
        StringBuilder sb = new StringBuilder();
        for (char c : word1.toCharArray()) {
            if (!enc.containsKey(c)) return "";
            sb.append(enc.get(c));
        }
        return sb.toString();
    }

    public int decrypt(String word2) {
        return counts.getOrDefault(word2, 0);
    }
}

/**
 * @param {character[]} keys
 * @param {string[]} values
 * @param {string[]} dictionary
 */
var Encrypter = function(keys, values, dictionary) {
    this.enc = new Map();
    for (let i = 0; i < keys.length; i++) {
        this.enc.set(keys[i], values[i]);
    }
    this.counts = new Map();
    for (const w of dictionary) {
        const e = this.encrypt(w);
        if (e.length > 0) {
            this.counts.set(e, (this.counts.get(e) || 0) + 1);
        }
    }
};

/** 
 * @param {string} word1
 * @return {string}
 */
Encrypter.prototype.encrypt = function(word1) {
    let res = '';
    for (const c of word1) {
        if (!this.enc.has(c)) return '';
        res += this.enc.get(c);
    }
    return res;
};

/** 
 * @param {string} word2
 * @return {number}
 */
Encrypter.prototype.decrypt = function(word2) {
    return this.counts.get(word2) || 0;
};
